import{_ as s,a0 as i,w as a,s as u,ao as g,I as p,a1 as o,A as e,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux中grep命令的12個實踐例子 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中grep命令的12個實踐例子 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中grep命令的12個實踐例子 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中grep命令的12個實踐例子 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/12 Practical Examples of Linux grep Command","title":"Linux中grep命令的12個實踐例子","tag":"201311","desc":""},"relativePath":"201311/12 Practical Examples of Linux grep Command.md","filePath":"[post].md"}'),l={name:"201311/12 Practical Examples of Linux grep Command.md"};function d(m,t,f,c,x,T){const n=i("Link");return a(),u("div",null,[t[12]||(t[12]=g(`<h1 id="linux中grep命令的12個實踐例子" tabindex="-1">Linux中grep命令的12個實踐例子 <a class="header-anchor" href="#linux中grep命令的12個實踐例子" aria-label="Permalink to “Linux中grep命令的12個實踐例子”">​</a></h1><p>你是否遇到過需要在文件中查找一個特定的字符串或者樣式，但是不知道從哪兒開始？那麼,就請<strong>grep</strong>來幫你吧。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2013/11/Grep-Command-Examples.png" alt=""></p><p><strong>grep</strong>是每個<strong>Linux</strong>發行版都預裝的一個強有力的文件模式搜索工具。無論何種原因，如果你的系統沒有預裝它的話，你可以很容易的通過系統的包管理器來安裝它（<strong>Debian/Ubuntu</strong>系中的<strong>apt-get</strong>和<strong>RHEl/CentOS/Fedora</strong>系中的<strong>yum</strong>）。</p><pre><code> $ sudo apt-get install grep               #Debian/Ubuntu
 
 $ sudo yum install grep                   #RHEL/CentOS/Fedora
</code></pre><p>我發現使用現實世界中的真實例子讓你投身其中是讓你接觸<strong>grep</strong>命令的最容易方式。</p><p>###1.搜索和尋找文件</p><p>假設你已經在你的電腦上安裝了一個全新的<strong>Ubuntu</strong>，然後你打算卸載<strong>Python</strong>。你瀏覽網頁尋找教程，但是你發現存在兩個不同版本的<strong>Python</strong>在使用，而你不知道你的<strong>Ubuntu</strong>安裝器到底在你的系統中安裝了哪個版本的Python，也不知道它安裝了哪些模組。解決這個煩惱只需簡單的運行以下命令：</p><pre><code>  $ sudo dpkg -l | grep -i python
</code></pre><p>####輸出例子 ii python2.7 2.7.3-0ubuntu3.4 Interactive high-level object-oriented language (version 2.7) ii python2.7-minimal 2.7.3-0ubuntu3.4 Minimal subset of the Python language (version 2.7) ii python-openssl 0.12-1ubuntu2.1 Python wrapper around the OpenSSL library ii python-pam 0.4.2-12.2ubuntu4 A Python interface to the PAM library</p><p>首先，我們運行<strong>dpkg -l</strong>列出你係統上安裝的<strong>.deb</strong>包。接着，我們使用管道將輸出結果傳輸給命令<strong>grep -i</strong> python，這一步可以簡單解釋為把結果傳輸給grep然後過濾出所有含有python的項，並返回結果。–i選項用於忽略大小寫,因為 grep 是大小寫敏感的。使用選項<strong>-i</strong>是個好習慣，除非你打算進行更細節的搜索。</p><p>###2.搜索和過濾文件</p><p>grep還可以在一個或多個文件裏用於搜索和過濾。讓我們來看一個這樣的情景：</p><p>你的<strong>Apache網頁服務器</strong>出現了問題，你不得不從許多專業網站裏找一個發帖詢問。好心回覆你的人讓你粘貼上來你的<strong>/etc/apache2/sites-available/default-ssl</strong>文件內容。假如你能移除掉所有的註釋行，那麼對你，對幫你的人，以及所有閲讀該文件的人，不是更容易發現問題嗎？你當然可以很容易的做到！只需這樣做就可以了：</p><pre><code> $ sudo grep -v &quot;#&quot; /etc/apache2/sites-available/default-ssl
</code></pre><p>選項<strong>-v</strong>是告訴<strong>grep</strong>命令反轉它的輸出結果，意思就是不輸出匹配的項，做相反的事，打印出所有不匹配的項。這個例子中，有<strong>#</strong>的是註釋行（譯註：其實這個命令並不準確，包含“#”的行不全是註釋行。關於如何精確匹配註釋行，可以瞭解更多的關於正則表達式的內容。）。</p><p>###3.找出所有的mp3文件</p><p><strong>grep</strong>命令對於過濾來自於<strong>標準輸出</strong>的結果非常有用。例如，假設你的一個文件夾裏面全是各種格式的音樂文件。你要找出藝術家<strong>jayZ</strong>的所有<strong>mp3</strong>格式的音樂文件，裏面也不要有任何混合音軌。使用<strong>find命令</strong>再結合管道使用<strong>grep</strong>就可以完成這個魔法：</p><pre><code> $ sudo find . -name &quot;.mp3&quot; | grep -i JayZ | grep -vi &quot;remix&quot;&quot;
</code></pre><p>在這個例子中，我們使用find命令打印出所有以<strong>.mp3</strong>為後綴名的文件，接着將其使用管道傳遞給<strong>grep -i</strong>過濾和打印出名字為“<strong>JayZ</strong>”的文件,再使用管道傳送給<strong>grep -vi</strong>以便過濾掉含有“<strong>remix</strong>”的項。</p>`,20)),p("ul",null,[p("li",null,[o(n,{href:"http://www.tecmint.com/35-practical-examples-of-linux-find-command/"},{default:e(()=>[...t[0]||(t[0]=[r("35個Linux中find命令的實踐例子",-1)])]),_:1})])]),t[13]||(t[13]=g(`<p>###4.在搜索字符串前面或者後面顯示行號</p><p>另外兩個選項是-A和-B之間的切換，是用以顯示匹配的行以及行號，分別控制在字符串前或字符串後顯示的行數。Man頁給出了更加詳細的解釋，我發現一個記憶的小竅門：-A=after、-B=before。</p><pre><code> $ sudo ifconfig | grep -A 4 etho
 $ sudo ifconfig | grep -B 2 UP
</code></pre><p>###5.在匹配字符串周圍打印出行號</p><p>grep命令的<strong>-C</strong>選項和例4中的很相似，不過打印的並不是在匹配字符串的前面或後面的行，而是打印出兩個方向都匹配的行（譯註：同上面的記憶竅門一樣：-C=center，以此為中心）： $ sudo ifconfig | grep -C 2 lo</p><p>###6.計算匹配項的數目</p><p>這個功能類似於將<strong>grep</strong>輸出的結果用管道傳送給計數器（<strong>wc</strong>程序），grep內建的選項可以達到同樣的目的：</p><pre><code>$ sudo ifconfig | grep -c inet6
</code></pre><p>###7.按給定字符串搜索文件中匹配的行號</p><p>當你在編譯出錯時需要調試時，<strong>grep</strong>命令的<strong>-n</strong>選項是個非常有用的功能。它能告訴你所搜索的內容在文件的哪一行：</p><pre><code>$ sudo grep -n &quot;main&quot; setup.py
</code></pre><p>###8.在所有目錄裏遞歸的搜索</p><p>假若你要在當前文件夾裏搜索一個字符串，而當前文件夾裏又有很多子目錄，你可以指定一個<strong>-r</strong>選項以便於遞歸的搜索： $ sudo grep -r &quot;function&quot; *</p><p>###9.進行精確匹配搜索</p><p>傳遞<strong>-w</strong>選項給grep命令可以在字符串中進行精確匹配搜索（譯註：包含要搜索的單詞，而不是通配）。例如，像下面這樣輸入：</p><pre><code>$ sudo ifconfig | grep -w “RUNNING”
</code></pre><p>將打印出含有引號內匹配項的行。另外，你還可以試一下這個：</p><pre><code>$ sudo ifconfig | grep -w “RUN”
</code></pre><p>搜索這個匹配項時，若搜索的東西里面沒有這樣的一個單獨的單詞，將什麼也不會返回。</p><p>###10.在Gzip壓縮文件中搜索</p><p>我們還要關注一下grep的衍生應用。第一個是<strong>zgrep</strong>，這個與<strong>zcat</strong>很相似，可以用於<strong>gzip</strong>壓縮過的文件。它有與<strong>grep</strong>相似的命令選項，使用方式也一樣：</p><pre><code>$ sudo zgrep -i error /var/log/syslog.2.gz
</code></pre><p>###11.在文件中匹配正則表達式</p><p><strong>egrep</strong>是另一個衍生應用，代表着“<strong>擴展全局正則表達式</strong>”。它可以識別更多的正則表達式元字符，例如<strong>at + ?</strong> | 和<strong>（）</strong>。在搜索源代碼文件時，egrep是一個非常有用的工具，還有其他的一些零碎代碼文件的搜索需要，使得這樣的搜索能力成為必需。可以在grep命令中使用選項<strong>-E</strong>來啓用它。</p><p>$ sudo grep -E</p><p>###12.搜索一個固定匹配字符串</p><p><strong>fgrep</strong>用於在一個文件或文件列表中搜索固定樣式的字符串。功能與<strong>grep -F</strong>同。<strong>fgrep</strong>的一個通常用法為傳遞一個含有樣式的文件給它：</p><pre><code>$ sudo fgrep -f file_full_of_patterns.txt file_to_search.txt
</code></pre><p>這僅僅是<strong>grep</strong>命令的開始，你可能已經注意到，它對於實現各種各樣的需求簡直是太有用了。除了這種我們運行的這種只有一行的命令，<strong>grep</strong>還可以寫成<strong>cron</strong>任務或者自動的<strong>shell腳本</strong>去執行。保持好奇心，試驗一下<strong>man頁</strong>的各個選項，為實現你的目的寫出一些<strong>grep表達式</strong>吧。</p><hr>`,30)),p("p",null,[t[2]||(t[2]=r("via: ",-1)),o(n,{href:"http://www.tecmint.com/12-practical-examples-of-linux-grep-command/"},{default:e(()=>[...t[1]||(t[1]=[r("http://www.tecmint.com/12-practical-examples-of-linux-grep-command/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=r("譯者：",-1)),o(n,{href:"https://github.com/Linux-pdz"},{default:e(()=>[...t[3]||(t[3]=[r("Linux-pdz",-1)])]),_:1}),t[6]||(t[6]=r(" 校對：",-1)),o(n,{href:"https://github.com/jasminepeng"},{default:e(()=>[...t[4]||(t[4]=[r("jasminepeng",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=r("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[7]||(t[7]=[r("LCTT",-1)])]),_:1}),t[10]||(t[10]=r(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[8]||(t[8]=[r("Linux中國",-1)])]),_:1}),t[11]||(t[11]=r(" 榮譽推出",-1))])])}const h=s(l,[["render",d]]);export{_ as __pageData,h as default};
